/**
 * Coerce unknown values to string for DOM / templates (avoids [object Object] in ESLint no-base-to-string).
 */
export function coerceStr(value: unknown, fallback = ''): string {
  if (typeof value === 'string') return value.length > 0 ? value : fallback;
  if (value == null) return fallback;
  if (typeof value === 'number' || typeof value === 'boolean' || typeof value === 'bigint') {
    return String(value);
  }
  return fallback;
}

/** Like `primary || fallback` but safe when primary may be a non-string object. */
export function coalesceStr(primary: unknown, fallback: string): string {
  if (typeof primary === 'string' && primary.length > 0) return primary;
  return fallback;
}
